--[[
* PartyramaXI - weaknesses, resistances and immunities of the target, like MobDB (2.7.7).
*
* The data comes from LandSandBoat (pximobdata.lua via pximob.lua, generated by the test kit's lsbgen_mob.py from the
* server's data\ecosystems.yaml and data\zones\*\mobs.yaml): the species' resistances with the monster's own changes
* on top. A monster is found by its server id (every spawn LandSandBoat lists), else by zone and name. Retail and other
* servers may differ.
*
* What is shown, as one more layer of the enemy bar:
*   elements      icons\elements\<Element>.png   weak (rank below 0) / resists (rank from "Resists from") / nullifies (10+)
*   damage types  icons\weak\<Type>.png          slashing, piercing, blunt, hand-to-hand, magic: more / less damage taken
*   immunities    the status effect's own icon, crossed out (immune, or resistance rank 10+)
*   status        2.9.3: the status effect's own icon, marked weak (rank below 0) / resists (rank from "Resists from")
* 2.9.3: the corner shows either the arrows or the change as a number (Marks: Arrows / +/- %). A rank is turned into
* the change the way LandSandBoat's resistance tiers go: -3 = +50%, -2 = +30%, -1 = +15%, 1 = -15%, 2 = -30%, 3 = -40%,
* 4 = -50%, 5 = -60%, 6 = -70%, 7 = -75%, 8 = -80%, 9 = -85%, 10 = -90%, 11 = -95%.
* A green mark points down for a weakness (two for a strong one), a red mark up for a resistance (2.9.1: like the
* evasion / defense arrows: up = strong against it, down = weak), a red line crosses
* out what does nothing. Hover the row for the details in words.
--]]
local imgui = require('imgui')
local Draw  = require('pxidraw')
local Info  = require('pxiinfo')
local Fonts = require('pxifonts')

local M = {}

local ELEM_FILE = { 'Fire.png', 'Ice.png', 'Wind.png', 'Earth.png', 'Lightning.png', 'Water.png', 'Light.png', 'Dark.png' }
local ELEM_NAME = { 'Fire', 'Ice', 'Wind', 'Earth', 'Lightning', 'Water', 'Light', 'Dark' }
local ELEM_COL = {
    { 0.92, 0.36, 0.22, 1 }, { 0.50, 0.80, 0.95, 1 }, { 0.35, 0.80, 0.40, 1 }, { 0.75, 0.60, 0.25, 1 },
    { 0.70, 0.45, 0.90, 1 }, { 0.25, 0.50, 0.90, 1 }, { 0.95, 0.92, 0.70, 1 }, { 0.45, 0.30, 0.60, 1 } }
local PHYS_FILE = { 'Slashing.png', 'Piercing.png', 'Blunt.png', 'H2H.png', 'Magic.png' }
local PHYS_NAME = { 'Slashing', 'Piercing', 'Blunt', 'Hand-to-hand', 'Magic' }
local PHYS_LABEL = { 'Sl', 'Pi', 'Bl', 'H2', 'Mg' }
local STEEL = { 0.20, 0.22, 0.26, 0.95 }
-- status rank keys -> status effect id (for the icon) and name
local STATUS = {
    { 'dark_sleep', 2, 'Sleep' }, { 'light_sleep', 2, 'Sleep (light)' }, { 'bind', 11, 'Bind' }, { 'gravity', 12, 'Gravity' },
    { 'silence', 6, 'Silence' }, { 'paralyze', 4, 'Paralyze' }, { 'slow', 13, 'Slow' }, { 'stun', 10, 'Stun' },
    { 'poison', 3, 'Poison' }, { 'blind', 5, 'Blind' }, { 'elegy', 194, 'Elegy' }, { 'requiem', 192, 'Requiem' },
    { 'terror', 28, 'Terror' }, { 'petrify', 7, 'Petrify' } }

M.png_elem, M.png_weak = nil, nil           -- Png objects for icons\elements\ and icons\weak\ (set by partyramaxi.lua)
M.find_icon, M.placeholder = nil, nil        -- the effect icons' status lookups (pxifx)

--------------------------------------------------------------------------- data
-- 2.8.0: the resistances are part of pximob's monster records (pximobdata.lua).
local Mob = require('pximob')
M.load = function () local ok = Mob.load(); M.load_error = Mob.load_error; return ok end
function M.lookup(sid, name)
    local r = Mob.lookup(sid, name)
    return r and r.K or nil
end
function M.kind_count() return Mob.kind_count() end
function M.range_count() return Mob.range_count() end

--------------------------------------------------------------------------- what to show
-- Entries: { kind = 'elem' | 'phys' | 'status', i = index, mark = 'weak' | 'weak2' | 'resist' | 'resist2' | 'null', status = id }
-- Order (2.10.0): damage types, elements, status effects; in each, weaknesses, resistances, then nullified / immune.
local function rank_mark(r, from)
    if r <= -2 then return 'weak2' elseif r < 0 then return 'weak'
    elseif r >= 10 then return 'null' elseif r >= from then return (r >= 7) and 'resist2' or 'resist' end
    return nil
end
local function pct_mark(p)
    if p >= 50 then return 'weak2' elseif p > 0 then return 'weak'
    elseif p <= -100 then return 'null' elseif p <= -50 then return 'resist2' elseif p < 0 then return 'resist' end
    return nil
end
local ORDER = { weak2 = 1, weak = 2, resist = 3, resist2 = 4, null = 5 }
local KIND_ORDER = { phys = 1, elem = 2, status = 3 }
-- resistance rank -> change in % (LandSandBoat's tiers: rank 4 = 50%, rank 6 = 30% of normal...)
local RANK_PCT = { [-3] = 50, [-2] = 30, [-1] = 15, [0] = 0, [1] = -15, [2] = -30, [3] = -40, [4] = -50, [5] = -60,
    [6] = -70, [7] = -75, [8] = -80, [9] = -85, [10] = -90, [11] = -95 }
local function rank_pct(r)
    r = math.max(-3, math.min(11, math.floor(r)))
    return RANK_PCT[r]
end
M.rank_pct = rank_pct
-- an element's % change and mark: MobDB's numbers as they are, LandSandBoat's ranks through the tiers
local function elem_pct(K, i)
    if K.ep then return tonumber(K.ep[i]) or 0 end
    return rank_pct(tonumber(K.e and K.e[i]) or 0)
end
local function elem_mark(K, i, from)
    if K.ep then return pct_mark(tonumber(K.ep[i]) or 0) end
    return rank_mark(tonumber(K.e and K.e[i]) or 0, from)
end
local PCT_STR = {}                           -- '+50%' / '-15%' strings, made once per value
local function pct_str(p)
    local t = PCT_STR[p]
    if t == nil then t = (p > 0 and '+' or '') .. p .. '%'; PCT_STR[p] = t end
    return t
end

-- Fills out with what cfg asks for; returns the count. Entries are reused.
function M.build(K, cfg, out)
    local n = 0
    local from = tonumber(cfg.resist_rank) or 4
    local function put(kind, i, mark, status, pct)
        if mark == nil then return end
        local weak = mark == 'weak' or mark == 'weak2'
        if weak and cfg.weak == false then return end
        if not weak and cfg.resist == false then return end
        n = n + 1
        local e = out[n]
        if e == nil then e = {}; out[n] = e end
        e.kind, e.i, e.mark, e.status, e.pct = kind, i, mark, status, pct
    end
    if cfg.elements ~= false and (K.e or K.ep) then
        -- "Only its biggest weaknesses": of the elements it is weak to, only the ones with the biggest change
        local best = 0
        if cfg.weak_best ~= false then for i = 1, 8 do best = math.max(best, elem_pct(K, i)) end end
        for i = 1, 8 do
            local v = elem_pct(K, i)
            if not (v > 0 and v < best) then put('elem', i, elem_mark(K, i, from), nil, v) end
        end
    end
    if cfg.physical ~= false and K.p then
        for i = 1, 5 do local v = tonumber(K.p[i]) or 0; put('phys', i, pct_mark(v), nil, v) end
    end
    -- 2.9.3: status effects it is weak to or resists (immune ones come below, crossed out). The two sleeps share an
    -- icon: light sleep only shows when it differs from dark sleep.
    if cfg.status ~= false and K.s then
        local ds = nil
        for _, st in ipairs(STATUS) do
            local r = tonumber(K.s[st[1]]) or 0
            if r < 10 then
                local m = rank_mark(r, from)
                if st[1] == 'dark_sleep' then ds = m
                elseif st[1] == 'light_sleep' and m == ds then m = nil end
                put('status', st[2], m, st[2], rank_pct(r))
            elseif st[1] == 'dark_sleep' then ds = 'null' end
        end
    end
    if cfg.immune ~= false and K.s then
        local seen2 = false
        for _, s in ipairs(STATUS) do
            local r = tonumber(K.s[s[1]])
            if r ~= nil and r >= 10 and not (s[2] == 2 and seen2) then
                if s[2] == 2 then seen2 = true end
                n = n + 1
                local e = out[n]
                if e == nil then e = {}; out[n] = e end
                e.kind, e.i, e.mark, e.status, e.pct = 'status', s[2], 'null', s[2], (r >= 99) and -100 or rank_pct(r)
            end
        end
    end
    -- 2.10.0: grouped weapon (damage types), then elements, then status effects (immunities last); within a group weak
    -- first, then resist, then null, each as listed above (a stable sort)
    for i = 2, n do
        local e = out[i]
        local k = KIND_ORDER[e.kind] * 10 + ORDER[e.mark]
        local j = i - 1
        while j >= 1 and KIND_ORDER[out[j].kind] * 10 + ORDER[out[j].mark] > k do out[j + 1] = out[j]; j = j - 1 end
        out[j + 1] = e
    end
    for i = n + 1, #out do out[i] = nil end
    return n
end

-- The hover text, cached per profile.
local TIP = setmetatable({}, { __mode = 'k' })
local function join(t) return table.concat(t, ', ') end
function M.tooltip(K, cfg, bare)
    local from = tonumber(cfg.resist_rank) or 4
    local key = TIP[K]
    if key and key.from == from and key.bare == (bare == true) then return key.text end
    local weak, res, null, imm, sweak, sres = {}, {}, {}, {}, {}, {}
    for i = 1, 8 do
        local m, v = elem_mark(K, i, from), elem_pct(K, i)
        if m == 'weak2' or m == 'weak' then weak[#weak + 1] = ELEM_NAME[i] .. ' ' .. pct_str(v)
        elseif m == 'null' then null[#null + 1] = ELEM_NAME[i] .. (v <= -100 and '' or ' ' .. pct_str(v))
        elseif m then res[#res + 1] = ELEM_NAME[i] .. ' ' .. pct_str(v) end
    end
    for _, s in ipairs(STATUS) do
        local r = tonumber(K.s and K.s[s[1]]) or 0
        if r < 10 then
            local m = rank_mark(r, from)
            if m == 'weak2' or m == 'weak' then sweak[#sweak + 1] = s[3] .. ' ' .. pct_str(rank_pct(r))
            elseif m then sres[#sres + 1] = s[3] .. ' ' .. pct_str(rank_pct(r)) end
        end
    end
    for i = 1, 5 do
        local p = tonumber(K.p and K.p[i]) or 0
        if p > 0 then weak[#weak + 1] = ('%s +%d%%'):format(PHYS_NAME[i], p)
        elseif p <= -100 then null[#null + 1] = PHYS_NAME[i]
        elseif p < 0 then res[#res + 1] = ('%s %d%%'):format(PHYS_NAME[i], p) end
    end
    for _, s in ipairs(STATUS) do
        local r = tonumber(K.s and K.s[s[1]])
        if r ~= nil and r >= 10 then imm[#imm + 1] = s[3] .. (r < 99 and ' (nearly)' or '') end
    end
    local lines = {}
    if #weak > 0 then lines[#lines + 1] = 'Weak to: ' .. join(weak) end
    if #res > 0 then lines[#lines + 1] = 'Resists: ' .. join(res) end
    if #null > 0 then lines[#lines + 1] = 'Nullifies: ' .. join(null) end
    if #sweak > 0 then lines[#lines + 1] = 'Effects land better: ' .. join(sweak) end
    if #sres > 0 then lines[#lines + 1] = 'Effects resisted: ' .. join(sres) end
    if #imm > 0 then lines[#lines + 1] = 'Immune to: ' .. join(imm) end
    if #lines == 0 then lines[1] = 'No known weaknesses or resistances.' end
    if #weak + #res + #null + #sweak + #sres > 0 then lines[#lines + 1] = '(Elements and effects: change in how well magic lands / hurts; damage types: damage taken.)' end
    if K.src == 'mobdb' then lines[#lines + 1] = '(Elements and damage types from MobDB; status effects from LandSandBoat.)'
    elseif not bare then lines[#lines + 1] = '(LandSandBoat data; your server may differ.)' end
    local text = table.concat(lines, '\n')
    TIP[K] = { from = from, text = text, bare = bare == true }
    return text
end

--------------------------------------------------------------------------- drawing
local Q1, Q2, Q3, Q4 = { 0, 0 }, { 0, 0 }, { 0, 0 }, { 0, 0 }
local UV1, UV2, UV3, UV4 = { 0, 0 }, { 1, 0 }, { 1, 1 }, { 0, 1 }
local V1, V2, V3 = { 0, 0 }, { 0, 0 }, { 0, 0 }
local WHITE = { 1, 1, 1, 1 }
local BLACK = { 0, 0, 0, 1 }
local GREEN, RED = { 0.40, 0.95, 0.45, 1 }, { 1.00, 0.30, 0.25, 1 }
local function vec(v, x, y) v[1], v[2] = x, y; return v end

local function image(dl, png, file, x0, y0, s, a)
    if png == nil then return false end
    local t = png:has(file) and png:get(file) or nil
    if t == nil or t.id == nil then return false end
    Q1[1], Q1[2], Q2[1], Q2[2], Q3[1], Q3[2], Q4[1], Q4[2] = x0, y0, x0 + s, y0, x0 + s, y0 + s, x0, y0 + s
    dl:AddImageQuad(t.id, Q1, Q2, Q3, Q4, UV1, UV2, UV3, UV4, Draw.u32(WHITE, a))
    return true
end

local function tile(dl, x0, y0, s, col, label, a, push, base)
    dl:AddRectFilled(vec(V1, x0, y0), vec(V2, x0 + s, y0 + s), Draw.u32(col, a), 3)
    local p = push and push(base * math.max(0.4, s / 34)) or false
    Info.text_at(dl, label, x0 + s / 2, y0 + s / 2, 'center', Draw.u32(WHITE, a), Info.ST)
    if p then Fonts.pop() end
end

-- the corner mark: green triangle(s) down = weak, red up = resists, red line = nothing gets through
local function mark(dl, cfg, m, x0, y0, s, a, pct, push, base)
    local t = math.max(4, s * 0.36)
    local x1, y1 = x0 + s, y0 + s
    local weak = m == 'weak' or m == 'weak2'
    -- 2.9.3: the change as a number in the corner (a crossed line stays for what takes nothing at all)
    if cfg.marks == 'percent' and pct ~= nil and pct > -100 then
        local col = (weak and (cfg.weak_color or GREEN)) or (cfg.resist_color or RED)
        local p = push and push(base * math.max(0.4, s / 28) * (tonumber(cfg.pct_scale) or 1)) or false
        Info.text_at(dl, pct_str(pct), x1 + 1, y1 - s * 0.18, 'right', Draw.u32(col, a), Info.ST)
        if p then Fonts.pop() end
        return
    end
    if m == 'null' then
        local w = math.max(2, s * 0.12)
        dl:AddLine(vec(V1, x0 + 1, y1 - 1), vec(V2, x1 - 1, y0 + 1), Draw.u32(BLACK, 0.8 * a), w + 2)
        dl:AddLine(vec(V1, x0 + 1, y1 - 1), vec(V2, x1 - 1, y0 + 1), Draw.u32(cfg.null_color or RED, a), w)
        return
    end
    local count = (m == 'weak2' or m == 'resist2') and 2 or 1
    local col = (weak and (cfg.weak_color or GREEN)) or (cfg.resist_color or RED)
    for c = 1, count do
        local cx = x1 - t / 2 - (c - 1) * (t * 0.8)
        local cy = y1 - t / 2
        local h = t / 2
        if not weak then vec(V1, cx, cy - h); vec(V2, cx + h, cy + h * 0.8); vec(V3, cx - h, cy + h * 0.8)
        else vec(V1, cx - h, cy - h * 0.8); vec(V2, cx + h, cy - h * 0.8); vec(V3, cx, cy + h) end
        dl:AddTriangleFilled(V1, V2, V3, Draw.u32(col, a))
        dl:AddTriangle(V1, V2, V3, Draw.u32(BLACK, 0.85 * a), 1)
    end
end

local function mouse()
    local ok, x, y = pcall(imgui.GetMousePos)
    if not ok then return nil end
    if type(x) == 'table' then x, y = x.x or x[1], x.y or x[2] end
    return tonumber(x), tonumber(y)
end

-- Draws n entries centred / aligned on (x + dx, y + dy). Returns the rectangle it used.
function M.draw(dl, cfg, x, y, list, n, K, alpha, gx, gy, push, base, rec)
    if n <= 0 or alpha <= 0.01 then return end
    local s = tonumber(cfg.size) or 16
    local gap = tonumber(cfg.spacing) or 2
    local cols = math.max(1, math.floor(tonumber(cfg.per_row) or 10))
    local rows = math.ceil(n / cols)
    local ra = math.max(0.1, math.min(1, tonumber(cfg.resist_alpha) or 0.8))
    local bx0, by0, bx1, by1 = 1e9, 1e9, -1e9, -1e9
    for i = 1, n do
        local e = list[i]
        local r = math.floor((i - 1) / cols)
        local c = (i - 1) % cols
        local in_row = math.min(cols, n - r * cols)
        local rw = in_row * s + (in_row - 1) * gap
        local left = x + (tonumber(cfg.dx) or 0) + (gx or 0)
        if cfg.align == 'center' or cfg.align == nil then left = left - rw / 2 elseif cfg.align == 'right' then left = left - rw end
        local x0 = math.floor(left + c * (s + gap) + 0.5)
        local y0 = math.floor(y + (tonumber(cfg.dy) or 0) + (gy or 0) - s / 2 + (cfg.rows_up and -r or r) * (s + gap) + 0.5)
        local a = alpha * ((e.mark == 'weak' or e.mark == 'weak2') and 1 or ra)
        if e.kind == 'elem' then
            if not image(dl, M.png_elem, ELEM_FILE[e.i], x0, y0, s, a) then tile(dl, x0, y0, s, ELEM_COL[e.i], ELEM_NAME[e.i]:sub(1, 2), a, push, base) end
        elseif e.kind == 'phys' then
            if not image(dl, M.png_weak, PHYS_FILE[e.i], x0, y0, s, a) then tile(dl, x0, y0, s, STEEL, PHYS_LABEL[e.i], a, push, base) end
        else
            local ic = M.find_icon and M.find_icon(e.status)
            local drew = false
            if ic then
                local t = ic.png:get(ic.file)
                if t.id ~= nil then
                    Q1[1], Q1[2], Q2[1], Q2[2], Q3[1], Q3[2], Q4[1], Q4[2] = x0, y0, x0 + s, y0, x0 + s, y0 + s, x0, y0 + s
                    dl:AddImageQuad(t.id, Q1, Q2, Q3, Q4, UV1, UV2, UV3, UV4, Draw.u32(WHITE, a))
                    drew = true
                end
            end
            if not drew then
                local l = M.placeholder and M.placeholder(e.status)
                tile(dl, x0, y0, s, l and l.col or STEEL, l and l.label or '?', a, push, base)
            end
        end
        mark(dl, cfg, e.mark, x0, y0, s, alpha, e.pct, push, base)
        if x0 < bx0 then bx0 = x0 end
        if y0 < by0 then by0 = y0 end
        if x0 + s > bx1 then bx1 = x0 + s end
        if y0 + s > by1 then by1 = y0 + s end
    end
    Draw.hl_rect('info', 'weak', bx0, by0, bx1, by1)
    if cfg.tooltip ~= false and K ~= nil then
        -- with the monster's record: the whole card (weaknesses in it); else just the weaknesses. Both are drawn last,
        -- in front of everything (Mob.flush).
        if rec ~= nil then Mob.hover(rec, bx0, by0, bx1, by1, M.tooltip(K, cfg, true))
        else
            local mx, my = mouse()
            if mx ~= nil and mx >= bx0 and mx <= bx1 and my >= by0 and my <= by1 then Mob.show_text(M.tooltip(K, cfg)) end
        end
    end
    return bx0, by0, bx1, by1
end

--------------------------------------------------------------------------- MobDB's data
-- 2.9.4: when ThornyFFXI's MobDB addon is installed, its data files (addons\mobdb\data\<zone>.lua, made from your
-- server's own source) give the element and damage-type numbers MobDB shows: damage taken multipliers, 1.25 = +25%.
-- MobDB has no status resistances, so those (and only those) still come from LandSandBoat; its immunities are added.
M.mdb_dir = nil                              -- '...\addons\mobdb\data\' (set by partyramaxi.lua), nil = not looked for
local MDB_ELEM = { 'Fire', 'Ice', 'Wind', 'Earth', 'Lightning', 'Water', 'Light', 'Dark' }
local MDB_PHYS = { 'Slashing', 'Piercing', 'Impact', 'H2H' }
local MDB_IMM = { [0x01] = { 'dark_sleep', 'light_sleep' }, [0x02] = { 'gravity' }, [0x04] = { 'bind' }, [0x08] = { 'stun' },
    [0x10] = { 'silence' }, [0x20] = { 'paralyze' }, [0x40] = { 'blind' }, [0x80] = { 'slow' }, [0x100] = { 'poison' },
    [0x200] = { 'elegy' }, [0x400] = { 'requiem' }, [0x800] = { 'light_sleep' }, [0x1000] = { 'dark_sleep' }, [0x2000] = { 'petrify' } }
local MDB = { zone = nil, names = nil, K = {} }
local mdb_seen = nil                         -- MobDB's data found (nil = not looked yet)
local function mdb_pct(m)                    -- multiplier -> whole % change, toward zero like MobDB (0.875 = -12)
    m = tonumber(m) or 1
    local v = (m - 1) * 100
    return v >= 0 and math.floor(v + 1e-6) or -math.floor(-v + 1e-6)
end
local function mdb_zone(zone)
    if MDB.zone == zone then return MDB.names end
    MDB.zone, MDB.names, MDB.K = zone, false, {}
    if M.mdb_dir == nil then return false end
    local fh = io.open(M.mdb_dir .. tostring(zone) .. '.lua', 'r')
    if fh == nil then return false end
    local src = fh:read('*a'); fh:close()
    local f = load(src, '@mobdb ' .. tostring(zone))
    if f == nil then return false end
    if setfenv then setfenv(f, {}) end       -- data only: the file gets no globals
    local ok, t = pcall(f)
    if ok and type(t) == 'table' and type(t.Names) == 'table' then MDB.names = t.Names; mdb_seen = true end
    return MDB.names
end
-- MobDB's profile for this monster as a K table (ep = element % changes), or nil when MobDB has no data for it.
function M.mobdb(sid, name, lsbK)
    if type(sid) ~= 'number' or sid == 0 or type(name) ~= 'string' then return nil end
    local zone = math.floor(sid / 4096) % 4096
    local names = mdb_zone(zone)
    if not names then return nil end
    local K = MDB.K[name]
    if K == nil then
        local r = names[name]
        local mo = type(r) == 'table' and r.Modifiers
        if type(mo) ~= 'table' then K = false
        else
            K = { src = 'mobdb', ep = {}, p = {}, s = {} }
            for i = 1, 8 do K.ep[i] = mdb_pct(mo[MDB_ELEM[i]]) end
            for i = 1, 4 do K.p[i] = mdb_pct(mo[MDB_PHYS[i]]) end
            K.p[5] = 0                                                -- K.p: slashing, piercing, blunt (Impact), h2h, magic
            if lsbK and lsbK.s then for k, v in pairs(lsbK.s) do K.s[k] = v end end
            local imm = tonumber(r.Immunities) or 0
            for f, keys in pairs(MDB_IMM) do
                if imm % (f * 2) >= f then for _, k in ipairs(keys) do K.s[k] = 99 end end
            end
        end
        MDB.K[name] = K
    end
    return K or nil
end
-- is MobDB's data there? (checked once; the settings window shows it)
function M.mdb_found()
    if mdb_seen == nil then
        mdb_seen = false
        if M.mdb_dir ~= nil then
            for z = 1, 300 do
                local fh = io.open(M.mdb_dir .. z .. '.lua', 'r')
                if fh then fh:close(); mdb_seen = true; break end
            end
        end
    end
    return mdb_seen
end
function M.mobdb_forget() MDB.zone, MDB.names, MDB.K = nil, nil, {} end

M.ELEM_NAME, M.PHYS_NAME, M.STATUS = ELEM_NAME, PHYS_NAME, STATUS
return M
